function qchart(q25,q26,qt){const W=560,H=250,L=62,R=16,T=14,B=32,mx=Math.max(...q25,...q26,...(qt||[]).map(v=>v||0));if(!(mx>0))return'<p class="muted small">Chưa có doanh số theo quý.</p>';
 const st=10**Math.floor(Math.log10(mx)),top=Math.ceil(mx/st)*st,y=v=>T+(H-T-B)*(1-v/top),gw=(W-L-R)/4,bw=gw*.26,base=y(0),
 lg=(b,f,l)=>`<span style="display:inline-flex;align-items:center;gap:6px"><i style="display:inline-block;width:14px;height:12px;border:2px solid ${b};background:${f}"></i>${l}</span>`,
 rect=(x,v,s,f,t,n)=>v>0?`<rect class="qbar" style="--i:${n*80}" x="${x.toFixed(1)}" y="${y(v).toFixed(1)}" width="${bw.toFixed(1)}" height="${(base-y(v)).toFixed(1)}" fill="${f}" stroke="${s}" stroke-width="2"><title>${t}: ${fmt(v)} VND</title></rect>`:"";
 return`<div class="small muted" style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:6px">${lg("var(--info)","var(--surface)","2025")}${lg("var(--text)","var(--accent)","2026")}${qt?'<span style="display:inline-flex;align-items:center;gap:6px"><i style="display:inline-block;width:18px;border-top:3px solid var(--text)"></i>Mục tiêu</span>':""}</div><svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto" role="img" aria-label="Biểu đồ cột doanh số theo quý: 2025, 2026 và mục tiêu 2026. Số liệu chi tiết có trong bảng bên cạnh.">`
 +[0,1,2,3,4].map(i=>{const v=top*i/4,yy=y(v);return`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="var(--border)"/><text x="${L-8}" y="${yy+4}" text-anchor="end" font-size="11" fill="var(--text-secondary)">${fmtB(v).replace(" triệu"," tr")}</text>`}).join("")
 +[0,1,2,3].map(k=>{const x0=L+k*gw+gw*.17,x1=x0+bw+6;return rect(x0,q25[k],"var(--info)","var(--surface)","Quý "+(k+1)+" năm 2025",k*2)+rect(x1,q26[k],"var(--text)","var(--accent)","Quý "+(k+1)+" năm 2026",k*2+1)+(qt&&qt[k]>0?`<line class="qline" pathLength="1" style="--i:${k*90+500}" x1="${(L+k*gw+gw*.1).toFixed(1)}" x2="${(L+(k+1)*gw-gw*.1).toFixed(1)}" y1="${y(qt[k]).toFixed(1)}" y2="${y(qt[k]).toFixed(1)}" stroke="var(--text)" stroke-width="3"><title>Mục tiêu quý ${k+1}: ${fmt(qt[k])} VND</title></line>`:"")+`<text x="${(L+k*gw+gw/2).toFixed(1)}" y="${H-10}" text-anchor="middle" font-size="12" fill="var(--text-secondary)">Quý ${k+1}</text>`}).join("")+"</svg>"}
function trend(mt,last){const W=640,H=250,L=62,R=16,T=14,B=30,mx=Math.max(...mt.flat());if(!(mx>0))return'<p class="muted small">Chưa có doanh số theo tháng. Hãy nhập từ Excel hoặc nhập số liệu tháng ở màn hình sửa khách hàng.</p>';
 const st=10**Math.floor(Math.log10(mx)),top=Math.ceil(mx/st)*st,x=i=>L+i*(W-L-R)/11,y=v=>T+(H-T-B)*(1-v/top),pts=(k,n)=>mt.slice(0,n).map((m,i)=>x(i).toFixed(1)+","+y(m[k]).toFixed(1)).join(" "),
 dots=(k,n,f)=>mt.slice(0,n).map((m,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(m[k]).toFixed(1)}" class="tdot" style="--i:${Math.round(i/11*1400)}" r="4" ${f}><title>Tháng ${i+1}/${k?2026:2025}: ${fmt(m[k])} VND</title></circle>`).join("");
 const base=y(0).toFixed(1),area=last>=0?`<polygon class="tarea" fill="var(--accent)" fill-opacity=".2" points="${pts(1,last+1)} ${x(last).toFixed(1)},${base} ${x(0).toFixed(1)},${base}"/>`:"";
 return`<div class="small muted" style="display:flex;gap:16px;margin-bottom:6px"><span><b style="color:var(--info)">┄┄</b> 2025</span><span><b>━━</b> 2026</span></div><svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto" role="img" aria-label="Biểu đồ đường doanh số theo tháng, 2025 so với 2026"><defs><clipPath id="trclip"><rect x="0" y="0" width="${W}" height="${H}"/></clipPath></defs>`+[0,1,2,3,4].map(i=>{const v=top*i/4,yy=y(v);return`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="var(--border)"/><text x="${L-8}" y="${yy+4}" text-anchor="end" font-size="11" fill="var(--text-secondary)">${fmtB(v).replace(" triệu"," tr")}</text>`}).join("")+mt.map((_,i)=>`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="11" fill="var(--text-secondary)">T${i+1}</text>`).join("")+`<g clip-path="url(#trclip)">${area}<polyline fill="none" stroke="var(--info)" stroke-width="2" stroke-dasharray="6 4" points="${pts(0,12)}"/>${dots(0,12,'fill="var(--surface)" stroke="var(--info)" stroke-width="2"')}`+(last>=0?`<polyline fill="none" stroke="var(--text)" stroke-width="3" points="${pts(1,last+1)}"/>${dots(1,last+1,'fill="var(--accent)" stroke="var(--text)" stroke-width="2"')}`:"")+"</g></svg>"}
function insights(mt,last){let b=-1;mt.forEach((m,i)=>{if(m[1]>0&&(b<0||m[1]>mt[b][1]))b=i});const n=last+1,y26=mt.reduce((s,m)=>s+m[1],0),y25=mt.slice(0,n).reduce((s,m)=>s+m[0],0);
 return[["Tháng cao nhất 2026",b<0?"–":"T"+(b+1)+" · "+fmtB(mt[b][1])],["Trung bình/tháng 2026",last<0?"–":fmtB(y26/n)],["So với cùng kỳ 2025",last<0||!y25?"–":pct(y26/y25-1)]].map(([l,v])=>`<div style="background:var(--surface-subtle);border-radius:var(--radius-md);padding:12px"><div class="muted tiny">${l}</div><strong>${v}</strong></div>`).join("")}
/* ===== v0.9.3: KPI năm chỉnh tay + Bản đồ khách hàng theo khu vực ===== */
