  done=true;if(commit&&v!==old){const arr=[...kpMonths()];arr[i]=v;S.prefs={...S.prefs,id:"prefs",kpi26m:arr};cust();const prev=[...kpMonths()];prev[i]=old;await kpSaveRaw(arr,prev,"Đã lưu KPI 2026 tháng "+(i+1))}else cust();
  const cells=[...document.querySelectorAll("#customer-foot .kpcell")],k=cells.findIndex(x=>+x.dataset.i===i),nx=dir==="right"?cells[k+1]:dir==="left"?cells[k-1]:null;
